import { useCallback, useEffect, useRef, useState } from "react";

export type ThemeMode = "light" | "dark" | "system";

export interface ThemeAppliedState {
  isDark: boolean;
  /** True when the OLED overlay is active (dark mode + extraDark). */
  extraDark: boolean;
  /** The value written to meta[name="theme-color"]. The PAGE background. */
  themeColor: string;
  /**
   * The frosted chrome (desktop header, sticky TabBar) as an OPAQUE colour --
   * `surface` mixed into `background` at `--frost-opacity`, which is what that
   * chrome composites to over the page.
   *
   * Native shells need this wherever something outside the webview paints the
   * area the chrome covers: the mobile TabBar reaches into the top safe area,
   * so an Android status-bar strip filled with `themeColor` sits a few levels
   * darker than the bar right below it. A launch background wants `themeColor`
   * instead -- it stands in for the page before anything has painted.
   */
  chromeColor: string;
}

export interface UseThemeOptions {
  /**
   * Controlled mode: pass the persisted preference (e.g. from a Dexie
   * settings row) and keep persistence app-side -- `setMode` becomes a no-op.
   * Omit to let the hook own persistence via `storageKey` (localStorage).
   */
  mode?: ThemeMode;
  /** Uncontrolled persistence key. Default: `wj-theme`. */
  storageKey?: string;
  /**
   * OLED overlay: in dark mode, additionally sets the DS `.extra-dark` class
   * (re-points dark surface tokens to pure black).
   *
   * Controlled/uncontrolled works exactly as `mode` does, and independently of
   * it. PASS it and the app owns the value -- `setExtraDark` becomes a no-op
   * (Chip Away keeps the flag in a Dexie settings row, where the hook storing
   * it too would be a second source of truth). OMIT it and the hook persists
   * the flag under `` `${storageKey}-extra-dark` `` and syncs every instance,
   * which is what an app with no database of its own wants -- otherwise each
   * one re-implements this hook's event-plus-`storage` sync to keep a Layout
   * that applies the class agreeing with a Settings page that sets it.
   */
  extraDark?: boolean;
  /**
   * meta[name="theme-color"] values. Omit them: the resolved color is read
   * from the DS background token that is actually painting the page, so an
   * app or theme that re-points `--color-background-*` is followed for free.
   * Only pass these for a bar color that deliberately differs from the page.
   */
  themeColors?: { light?: string; dark?: string; extraDark?: string };
  /**
   * When set, the resolved appearance (`'light' | 'dark' | 'oled'`) is
   * mirrored to this localStorage key on every apply, for an index.html
   * pre-paint script to read on the next launch (kills the first-frame
   * light-to-dark flash). Best-effort: storage errors are swallowed.
   */
  launchMirrorKey?: string;
  /**
   * Paint the resolved color onto `<html>` (default `true`) -- the cold-launch
   * flash backstop described on the apply effect below.
   *
   * Pass `false` for a window whose canvas must stay TRANSPARENT: the root
   * element's background propagates to the canvas, so painting it defeats a
   * `body { background: transparent }` rule and fills the whole window rect.
   * Chip Away's Linux build is the case -- an undecorated `transparent: true`
   * window whose rounded corners are pure CSS, and which needs genuine alpha
   * outside the rounded box to show them. Setting `false` also CLEARS any
   * color an index.html pre-paint script already set, so the opt-out still
   * holds when the app can only detect the platform after that script ran.
   */
  paintRoot?: boolean;
  /**
   * App-specific side effects after each apply -- native status-bar bridges,
   * window-chrome updates, and similar. Called with the resolved state.
   */
  onApplied?: (state: ThemeAppliedState) => void;
}

export interface UseThemeResult {
  /** The preference ('light' / 'dark' / 'system'). */
  mode: ThemeMode;
  /** Persist + broadcast a new preference. No-op in controlled mode. */
  setMode: (mode: ThemeMode) => void;
  /** The resolved appearance. */
  isDark: boolean;
  /**
   * The OLED preference, which is what a settings toggle binds to. This is the
   * preference rather than the resolved state: it stays true in light mode,
   * where the overlay does not apply. For the resolved state read `extraDark`
   * off `onApplied`, or `isDark && extraDark` here.
   */
  extraDark: boolean;
  /** Persist + broadcast a new OLED preference. No-op when `extraDark` is passed. */
  setExtraDark: (extraDark: boolean) => void;
}

const CHANGE_EVENT = "wj-theme-changed";
const DEFAULT_KEY = "wj-theme";
/**
 * Derived rather than a second option, so an app namespaces both halves of its
 * theme state by setting `storageKey` once.
 */
const EXTRA_DARK_SUFFIX = "-extra-dark";
/**
 * Last resort only, for when variables.css has not been applied (SSR, tests).
 * These mirror the `background.light` / `background.dark` tokens and the
 * `.dark.extra-dark` overlay; the live token wins whenever it can be read.
 */
const FALLBACK_COLORS = { light: "#e9e9e7", dark: "#181819", extraDark: "#000000" };

/**
 * Read a DS custom property off <html>, resolved against its CURRENT classes
 * (so `.dark.extra-dark` re-pointing `--color-background-dark` to black comes
 * out on its own). Returns `fallback` when no stylesheet has landed yet.
 */
/** `#rrggbb` -> [r,g,b]; null for anything else (a color-mix(), a var()). */
function parseHex(hex: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return null;
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/**
 * `fg` over `bg` at `ratio`, as a hex. The frosted chrome is a color-mix in
 * CSS, but a custom property holding one computes to the literal `color-mix(…)`
 * text, and a native bridge needs `#rrggbb` -- so the same mix is done here.
 */
function mixHex(fg: string, bg: string, ratio: number): string {
  const a = parseHex(fg);
  const b = parseHex(bg);
  if (!a || !b) return bg;
  const c = a.map((v, i) => Math.round(v * ratio + b[i] * (1 - ratio)));
  return `#${c.map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}

function readTokenColor(name: string, fallback: string): string {
  try {
    const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    return value || fallback;
  } catch {
    // Non-DOM environments and locked-down webviews.
    return fallback;
  }
}

function readStored(key: string): ThemeMode {
  try {
    const saved = localStorage.getItem(key);
    if (saved === "light" || saved === "dark" || saved === "system") return saved;
  } catch {
    // Locked-down webviews can throw; fall through to the default.
  }
  return "system";
}

function readStoredExtraDark(key: string): boolean {
  try {
    return localStorage.getItem(key) === "1";
  } catch {
    // Same webviews; the overlay is off by default.
    return false;
  }
}

/**
 * The one theme engine: resolves light/dark/system (live OS tracking), toggles
 * the `dark` / `.extra-dark` classes on <html>, keeps meta[name="theme-color"]
 * in sync, and -- uncontrolled -- persists the preference and syncs every hook
 * instance in the tab (plus other tabs) so Layout and Settings stay agreed.
 */
export function useTheme(options: UseThemeOptions = {}): UseThemeResult {
  const {
    mode: controlledMode,
    storageKey = DEFAULT_KEY,
    extraDark: controlledExtraDark,
    themeColors,
    launchMirrorKey,
    paintRoot = true,
    onApplied,
  } = options;
  const controlled = controlledMode !== undefined;
  // Independent of `controlled`: an app can control the mode from its own store
  // and still let the hook own the OLED flag, or the reverse.
  const extraDarkControlled = controlledExtraDark !== undefined;
  const extraDarkKey = `${storageKey}${EXTRA_DARK_SUFFIX}`;

  const [storedMode, setStoredMode] = useState<ThemeMode>(() =>
    controlled || typeof window === "undefined" ? "system" : readStored(storageKey),
  );
  const mode = controlled ? controlledMode : storedMode;

  const [storedExtraDark, setStoredExtraDark] = useState<boolean>(() =>
    extraDarkControlled || typeof window === "undefined"
      ? false
      : readStoredExtraDark(extraDarkKey),
  );
  const extraDark = extraDarkControlled ? controlledExtraDark : storedExtraDark;

  const [systemDark, setSystemDark] = useState(
    () => typeof window !== "undefined" && window.matchMedia("(prefers-color-scheme: dark)").matches,
  );

  // Track the OS preference so 'system' mode reacts live.
  useEffect(() => {
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    setSystemDark(mq.matches);
    const handler = (e: MediaQueryListEvent) => setSystemDark(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  // Uncontrolled: stay in sync with other hook instances (same tab) and other
  // tabs of the same app.
  useEffect(() => {
    if (controlled) return;
    const sync = () => setStoredMode(readStored(storageKey));
    window.addEventListener(CHANGE_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(CHANGE_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [controlled, storageKey]);

  // The same sync for the OLED flag, on the same event. Separate because the
  // two halves control independently: an app can pass `mode` and omit
  // `extraDark`, and then only this one runs.
  useEffect(() => {
    if (extraDarkControlled) return;
    const sync = () => setStoredExtraDark(readStoredExtraDark(extraDarkKey));
    window.addEventListener(CHANGE_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(CHANGE_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [extraDarkControlled, extraDarkKey]);

  const isDark = mode === "dark" || (mode === "system" && systemDark);
  const oled = isDark && extraDark;

  const onAppliedRef = useRef(onApplied);
  onAppliedRef.current = onApplied;

  const lightOverride = themeColors?.light;
  const darkOverride = themeColors?.dark;
  const oledOverride = themeColors?.extraDark;

  // Apply the resolved appearance.
  useEffect(() => {
    const root = document.documentElement;
    root.classList.toggle("dark", isDark);
    root.classList.toggle("extra-dark", oled);
    // Derive the bar color from the token that is painting the page, read
    // AFTER the class toggle so the `.extra-dark` overlay resolves itself. A
    // hardcoded copy here drifts silently the moment a background token moves
    // -- and it takes native chrome with it, because `onApplied` consumers
    // (Chip Away's Android status-bar bridge) paint whatever this resolves to.
    const themeColor = isDark
      ? oled
        ? oledOverride ?? readTokenColor("--color-background-dark", FALLBACK_COLORS.extraDark)
        : darkOverride ?? readTokenColor("--color-background-dark", FALLBACK_COLORS.dark)
      : lightOverride ?? readTokenColor("--color-background-light", FALLBACK_COLORS.light);
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", themeColor);

    // Read with the CURRENT classes applied, so `.dark.extra-dark` re-pointing
    // the dark surfaces comes out on its own.
    const surface = readTokenColor(
      isDark ? "--color-surface-dark" : "--color-surface-light",
      themeColor,
    );
    const frost = parseFloat(readTokenColor("--frost-opacity", "75%")) / 100;
    const chromeColor = mixHex(surface, themeColor, Number.isFinite(frost) ? frost : 0.75);
    // Paint the root element itself, not only the classes. The page background
    // normally comes from a `body` rule, which does not exist until the app's
    // render-blocking stylesheet has loaded -- so between navigation and that
    // load the canvas is the browser's or webview's own default (white), which
    // is the cold-launch flash. A pre-paint script in index.html cannot fix it
    // by toggling classes, because a class is inert without CSS; it CAN set this
    // property, and doing the same here keeps the root in sync for the rest of
    // the session so a later theme change does not leave a stale color behind.
    //
    // The root's background PROPAGATES TO THE CANVAS, which is why this reaches
    // the launch frame at all -- and equally why `paintRoot: false` exists: it
    // also overrides a transparent `body`, so a transparent window loses the
    // alpha it needs (see the option's doc). Clearing rather than skipping means
    // the opt-out also undoes a pre-paint script that ran before the app could
    // tell which platform it was on.
    root.style.backgroundColor = paintRoot ? themeColor : "";
    if (launchMirrorKey) {
      try {
        localStorage.setItem(launchMirrorKey, oled ? "oled" : isDark ? "dark" : "light");
      } catch {
        // Best-effort mirror.
      }
    }
    onAppliedRef.current?.({ isDark, extraDark: oled, themeColor, chromeColor });
  }, [isDark, oled, lightOverride, darkOverride, oledOverride, launchMirrorKey, paintRoot]);

  const setMode = useCallback(
    (next: ThemeMode) => {
      if (controlled) return;
      try {
        localStorage.setItem(storageKey, next);
      } catch {
        // The in-memory state still updates; persistence is best-effort.
      }
      setStoredMode(next);
      window.dispatchEvent(new Event(CHANGE_EVENT));
    },
    [controlled, storageKey],
  );

  const setExtraDark = useCallback(
    (next: boolean) => {
      if (extraDarkControlled) return;
      try {
        localStorage.setItem(extraDarkKey, next ? "1" : "0");
      } catch {
        // The in-memory state still updates; persistence is best-effort.
      }
      setStoredExtraDark(next);
      window.dispatchEvent(new Event(CHANGE_EVENT));
    },
    [extraDarkControlled, extraDarkKey],
  );

  return { mode, setMode, isDark, extraDark, setExtraDark };
}
